forever(function on_forever5() {
    
    if (info.life() <= 50 && tracker <= 0) {
        music.stopAllSounds()
        music.play(music.createSong(hex`
                
                `), music.PlaybackMode.LoopingInBackground)
        enemysoeed += -15
        tracker += 1
        info.changeScoreBy(100)
    }
    
    if (info.life() <= 10 && tracker <= 1) {
        music.stopAllSounds()
        music.play(music.createSong(hex`
                
                `), music.PlaybackMode.LoopingInBackground)
        enemysoeed += -15
        tracker += 1
        info.changeScoreBy(100)
    }
    
    if (mySprite.y < 60) {
        info.changeScoreBy(1)
    }
    
    if (info.score() >= 100 && scoretracker == 0) {
        enemysoeed += -15
        scoretracker += 1
        info.changeScoreBy(100)
    }
    
    if (info.score() >= 1000 && scoretracker == 3) {
        enemysoeed += -15
        scoretracker += 1
        info.changeScoreBy(100)
    }
    
    if (info.score() >= 10000 && scoretracker <= 4) {
        enemysoeed += -15
        scoretracker += 1
        info.changeScoreBy(100)
    }
    
    if (info.score() >= 200 && scoretracker <= 1) {
        enemysoeed += -15
        scoretracker += 1
        info.changeScoreBy(100)
    }
    
    if (info.score() >= 500 && scoretracker <= 2) {
        enemysoeed += -15
        scoretracker += 1
        info.changeScoreBy(100)
    }
    
    if (info.score() >= 1000000 && scoretracker <= 5) {
        info.changeScoreBy(100)
        game.gameOver(true)
    }
    
})
